def solve(s):
    def expand(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left+1:right]

    if not s:
        return ""

    longest = ""
    for i in range(len(s)):
        sub1 = expand(s, i, i)
        sub2 = expand(s, i, i+1)
        longest = max(longest, sub1, sub2, key=len)

    return longest
```

