def solve(s):
    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left+1:right]

    longest = ""
    for i in range(len(s)):
        # Odd length
        substr = expand_around_center(i, i)
        if len(substr) > len(longest):
            longest = substr
        # Even length
        substr = expand_around_center(i, i+1)
        if len(substr) > len(longest):
            longest = substr
    return longest
```

